def _check_registry() -> None:
    if len(_CONTRACTS) != len(_CONTRACT_BY_CASEFOLD):
        raise RuntimeError("human page template registry contains duplicate page types")
    for contract in _CONTRACTS:
        required_ids = [section.section_id for section in contract.required_sections]
        optional_ids = [section.section_id for section in contract.optional_sections]
        if len(required_ids) != len(set(required_ids)) or len(optional_ids) != len(set(optional_ids)):
            raise RuntimeError(f"human page template contains duplicate section ids: {contract.page_type}")
        if set(required_ids) & set(optional_ids):
            raise RuntimeError(f"human page template section is both required and optional: {contract.page_type}")
        for value in (contract.key_entity_budget, contract.source_link_budget):
            if value.minimum < 0 or value.maximum < value.minimum:
                raise RuntimeError(f"human page template contains an invalid budget: {contract.page_type}")
            if value.scope not in {"page", "entry"}:
                raise RuntimeError(f"human page template contains an invalid budget scope: {contract.page_type}")

def list_human_page_types() -> tuple[str, ...]:
    """Return the registry order as an immutable tuple."""

    return _PAGE_TYPE_ORDER

def _compatible_version(contract_version: str, schema_version: int) -> bool:
    return (
        schema_version == HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION
        and contract_version == HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION
    )

def _section_document(section: SectionContract) -> dict[str, Any]:
    return {
        "heading": section.heading,
        "heading_pattern": section.heading_pattern,
        "level": section.level,
        "purpose": section.purpose,
        "repeatable": section.repeatable,
        "section_id": section.section_id,
    }

def _budget_document(budget: CountBudget) -> dict[str, Any]:
    return {
        "counting_rule": budget.counting_rule,
        "maximum": budget.maximum,
        "minimum": budget.minimum,
        "overflow_action": budget.overflow_action,
        "scope": budget.scope,
    }

def human_page_template_registry_document(
    *,
    contract_version: str = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: int = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> dict[str, Any]:
    if not _compatible_version(contract_version, schema_version):
        get_human_page_template(
            "INDEX", contract_version=contract_version, schema_version=schema_version
        )
    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "page_type_order": list(_PAGE_TYPE_ORDER),
        "page_types": [human_page_template_document(contract) for contract in _CONTRACTS],
        "registry_id": HUMAN_PAGE_TEMPLATE_REGISTRY_ID,
        "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
        "status": "ready",
    }

def serialize_human_page_template_registry(
    *,
    contract_version: str = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: int = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> str:
    """Serialize with stable key ordering, page ordering, whitespace, and newline."""

    document = human_page_template_registry_document(
        contract_version=contract_version, schema_version=schema_version
    )
    return json.dumps(document, ensure_ascii=False, indent=2, sort_keys=True) + "\n"

def _visible_lines(markdown: str) -> list[tuple[int, str]]:
    visible: list[tuple[int, str]] = []
    fence: str | None = None
    for line_number, raw in enumerate(markdown.splitlines(), start=1):
        stripped = raw.lstrip()
        marker = stripped[:3]
        if marker in {"```", "~~~"}:
            if fence is None:
                fence = marker
            elif marker == fence:
                fence = None
            continue
        if fence is None:
            visible.append((line_number, raw))
    return visible

def _headings(markdown: str) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for line_number, line in _visible_lines(markdown):
        match = _HEADING_RE.match(line.strip())
        if match:
            result.append({"level": len(match.group(1)), "text": match.group(2).strip(), "line": line_number})
    return result

def _matches_section(heading: Mapping[str, Any], section: SectionContract) -> bool:
    if int(heading["level"]) != section.level:
        return False
    text = str(heading["text"])
    if section.heading_pattern:
        return re.fullmatch(section.heading_pattern, text) is not None
    return text == section.heading

def _effective_budget(
    budget: CountBudget,
    contract: HumanPageTemplateContract,
    headings: Sequence[Mapping[str, Any]],
) -> tuple[int, int, int]:
    units = 1
    if budget.scope == "entry":
        entry = next((section for section in contract.required_sections if section.section_id == "entry"), None)
        if entry is None:
            raise RuntimeError(f"entry-scoped budget has no entry section: {contract.page_type}")
        units = max(1, sum(1 for heading in headings if _matches_section(heading, entry)))
    return budget.minimum * units, budget.maximum * units, units

def _context_sequence(context: Mapping[str, Any], name: str, errors: list[dict[str, Any]]) -> list[Any]:
    value = context.get(name, [])
    if not isinstance(value, list):
        errors.append(_validation_error("validation-context-invalid", f"validation context 的 {name} 必须是数组。", field=name))
        return []
    return value

def _link_occurrences(markdown: str) -> list[dict[str, Any]]:
    text = "\n".join(line for _line_number, line in _visible_lines(markdown))
    links: list[dict[str, Any]] = []
    for match in _INLINE_LINK_RE.finditer(text):
        links.append({"label": match.group(1).strip(), "target": match.group(2).strip()})
    for match in _WIKILINK_RE.finditer(text):
        target = match.group(1).strip()
        alias = (match.group(2) or "").strip()
        links.append({"label": alias or target, "target": target})
    return links

def validate_human_page(
    page_type: str,
    markdown: str,
    *,
    context: Mapping[str, Any] | None = None,
    contract_version: str = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: int = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> dict[str, Any]:
    """Validate one page without network, LLM, mutable state, or hidden defaults.

    ``context`` owns information Markdown cannot classify reliably:

    - ``key_entities``: implementation entities counted by the page contract;
    - ``links``: optional ``target``, ``purpose``, and ``kind`` evidence;
    - ``current_facts``: exact fact line plus non-empty ``source`` and ISO
      ``observed_at``.
    """

    errors: list[dict[str, Any]] = []
    canonical_page_type = str(page_type).strip()
    if not _compatible_version(contract_version, schema_version):
        errors.append(
            _validation_error(
                "contract-version-incompatible",
                "人类页面模板合同版本不兼容。",
                actual={"schema_version": schema_version, "contract_version": contract_version},
                expected={
                    "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
                    "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
                },
            )
        )
        return {
            "contract_version": contract_version,
            "errors": errors,
            "page_type": canonical_page_type,
            "schema_version": schema_version,
            "status": "failed",
        }
    contract = _CONTRACT_BY_CASEFOLD.get(canonical_page_type.casefold())
    if contract is None:
        errors.append(
            _validation_error(
                "unknown-page-type",
                f"未知人类页面类型：{page_type}。",
                available=list(_PAGE_TYPE_ORDER),
            )
        )
        return {
            "contract_version": contract_version,
            "errors": errors,
            "page_type": canonical_page_type,
            "schema_version": schema_version,
            "status": "failed",
        }
    canonical_page_type = contract.page_type
    if not isinstance(markdown, str) or not markdown.strip():
        errors.append(_validation_error("page-empty", "人类页面正文不能为空。"))
        return {
            "contract_version": contract_version,
            "errors": errors,
            "page_type": canonical_page_type,
            "schema_version": schema_version,
            "status": "failed",
        }
    if not isinstance(context, Mapping) and context is not None:
        errors.append(_validation_error("validation-context-invalid", "validation context 必须是 JSON 对象。"))
        context = {}
    context = context or {}

    headings = _headings(markdown)
    h1 = [heading for heading in headings if heading["level"] == 1]
    if len(h1) != 1:
        errors.append(
            _validation_error(
                "title-heading-count",
                "人类页面必须且只能包含一个一级标题。",
                count=len(h1),
                lines=[heading["line"] for heading in h1],
            )
        )
    for section in contract.required_sections:
        matches = [heading for heading in headings if _matches_section(heading, section)]
        if not matches:
            errors.append(
                _validation_error(
                    "required-section-missing",
                    f"{contract.page_type} 页面缺少必填章节：{section.heading}。",
                    section_id=section.section_id,
                    heading=section.heading,
                    level=section.level,
                )
            )

    by_heading: dict[tuple[int, str], list[int]] = {}
    for heading in headings:
        by_heading.setdefault((int(heading["level"]), str(heading["text"])), []).append(int(heading["line"]))
    all_sections = contract.required_sections + contract.optional_sections
    for (level, text), lines in sorted(by_heading.items()):
        if len(lines) < 2:
            continue
        repeatable = any(
            section.repeatable
            and level == section.level
            and ((section.heading_pattern and re.fullmatch(section.heading_pattern, text)) or (not section.heading_pattern and text == section.heading))
            for section in all_sections
        )
        if not repeatable:
            errors.append(
                _validation_error(
                    "duplicate-heading",
                    f"人类页面包含重复标题：{text}。",
                    heading=text,
                    level=level,
                    lines=lines,
                )
            )

    visible_text = "\n".join(line for _line_number, line in _visible_lines(markdown))
    for pattern in _META_PATTERNS:
        match = pattern.search(visible_text)
        if match:
            line_number = visible_text[: match.start()].count("\n") + 1
            errors.append(
                _validation_error(
                    "process-meta-copy",
                    "人类页面包含制作过程元文案或占位符。",
                    text=match.group(0),
                    visible_line=line_number,
                )
            )

    key_entities = _context_sequence(context, "key_entities", errors)
    invalid_entities = [value for value in key_entities if not isinstance(value, str) or not value.strip()]
    if invalid_entities:
        errors.append(_validation_error("validation-context-invalid", "key_entities 只能包含非空字符串。", field="key_entities"))
    entity_count = len({str(value).strip() for value in key_entities if isinstance(value, str) and value.strip()})
    entity_budget = contract.key_entity_budget
    entity_minimum, entity_maximum, entity_units = _effective_budget(entity_budget, contract, headings)
    if entity_count < entity_minimum or entity_count > entity_maximum:
        errors.append(
            _validation_error(
                "key-entity-budget",
                f"{contract.page_type} 页面的关键实体数量为 {entity_count}，合同要求 {entity_minimum}..{entity_maximum}。",
                actual=entity_count,
                minimum=entity_minimum,
                maximum=entity_maximum,
                scope=entity_budget.scope,
                scope_units=entity_units,
                overflow_action=entity_budget.overflow_action,
            )
        )

    link_context = _context_sequence(context, "links", errors)
    purpose_by_target: dict[str, str] = {}
    kind_by_target: dict[str, str] = {}
    for index, item in enumerate(link_context):
        if not isinstance(item, Mapping):
            errors.append(_validation_error("validation-context-invalid", "links 条目必须是对象。", field=f"links[{index}]"))
            continue
        target = str(item.get("target") or "").strip()
        purpose = str(item.get("purpose") or "").strip()
        kind = str(item.get("kind") or "internal").strip()
        if not target or kind not in {"internal", "external", "source", "evidence"}:
            errors.append(_validation_error("validation-context-invalid", "links 条目需要 target，且 kind 必须是 internal、external、source 或 evidence。", field=f"links[{index}]"))
            continue
        purpose_by_target[target] = purpose
        kind_by_target[target] = kind
        if not purpose:
            errors.append(
                _validation_error(
                    "link-purpose-missing",
                    f"链接 {target} 没有说明阅读目的。",
                    target=target,
                )
            )
    source_link_count = 0
    for link in _link_occurrences(markdown):
        target = str(link["target"])
        label = re.sub(r"[`*_]", "", str(link["label"])).strip()
        explicit_purpose = purpose_by_target.get(target, "")
        if label in _AMBIGUOUS_LINK_LABELS and not explicit_purpose:
            errors.append(
                _validation_error(
                    "link-purpose-missing",
                    f"链接文字“{label}”没有说明阅读目的。",
                    label=label,
                    target=target,
                )
            )
        kind = kind_by_target.get(target)
        if kind == "source" or (kind is None and target.casefold().startswith("vscode://file/")):
            source_link_count += 1
    source_budget = contract.source_link_budget
    source_minimum, source_maximum, source_units = _effective_budget(source_budget, contract, headings)
    if source_link_count < source_minimum or source_link_count > source_maximum:
        errors.append(
            _validation_error(
                "source-link-budget",
                f"{contract.page_type} 页面的源码链接数量为 {source_link_count}，合同要求 {source_minimum}..{source_maximum}。",
                actual=source_link_count,
                minimum=source_minimum,
                maximum=source_maximum,
                scope=source_budget.scope,
                scope_units=source_units,
                overflow_action=source_budget.overflow_action,
            )
        )

    fact_context = _context_sequence(context, "current_facts", errors)
    fact_evidence: dict[str, Mapping[str, Any]] = {}
    for index, item in enumerate(fact_context):
        if not isinstance(item, Mapping):
            errors.append(_validation_error("validation-context-invalid", "current_facts 条目必须是对象。", field=f"current_facts[{index}]"))
            continue
        claim = _normalize_fact_line(str(item.get("claim") or ""))
        if not claim:
            errors.append(_validation_error("validation-context-invalid", "current_facts 条目需要非空 claim。", field=f"current_facts[{index}]"))
            continue
        fact_evidence[claim] = item
    for line_number, line in _visible_lines(markdown):
        normalized = _normalize_fact_line(line)
        if not normalized or normalized.startswith("#") or not _CURRENT_FACT_RE.search(normalized):
            continue
        evidence = fact_evidence.get(normalized)
        source = str(evidence.get("source") or "").strip() if evidence else ""
        observed_at = str(evidence.get("observed_at") or "").strip() if evidence else ""
        if not source or not _OBSERVED_AT_RE.fullmatch(observed_at):
            errors.append(
                _validation_error(
                    "current-fact-unverified",
                    "含当前状态的事实必须提供逐行匹配的 source 与 observed_at。",
                    claim=normalized,
                    line=line_number,
                )
            )

    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "errors": errors,
        "metrics": {
            "heading_count": len(headings),
            "key_entity_count": entity_count,
            "source_link_count": source_link_count,
            "verified_current_fact_count": sum(
                1
                for _line_number, line in _visible_lines(markdown)
                if _CURRENT_FACT_RE.search(_normalize_fact_line(line))
                and _normalize_fact_line(line) in fact_evidence
            ),
        },
        "page_type": canonical_page_type,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
    }

def _load_context(path: Path | None) -> Mapping[str, Any]:
    if path is None:
        return {}
    try:
        value = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise CkbError(f"模板 validation context 不是有效 JSON：{path}：{exc}") from exc
    if not isinstance(value, Mapping):
        raise CkbError(f"模板 validation context 必须是 JSON 对象：{path}")
    return value

def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.command == "registry":
            print(
                serialize_human_page_template_registry(
                    contract_version=args.contract_version,
                    schema_version=args.schema_version,
                ),
                end="",
            )
            return 0
        if args.command == "get":
            contract = get_human_page_template(
                args.page_type,
                contract_version=args.contract_version,
                schema_version=args.schema_version,
            )
            result = {
                "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
                "page_type": human_page_template_document(contract),
                "registry_sha256": human_page_template_registry_sha256(),
                "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
                "status": "ready",
            }
            print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
            return 0
        markdown = args.input.read_text(encoding="utf-8-sig")
        result = validate_human_page(
            args.page_type,
            markdown,
            context=_load_context(args.context),
            contract_version=args.contract_version,
            schema_version=args.schema_version,
        )
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if result["status"] == "passed" else 2
    except (CkbError, OSError, UnicodeError) as exc:
        result = {
            "contract_version": getattr(args, "contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
            "errors": [_validation_error("command-input-invalid", str(exc))],
            "schema_version": getattr(args, "schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
            "status": "failed",
        }
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 2

def _text_list(value: Any, name: str, maximum: int = 32) -> list[str]:
    if not isinstance(value, list) or not value or len(value) > maximum:
        raise CkbError(f"keyword benchmark {name} must contain 1 to {maximum} strings")
    if any(not isinstance(item, str) or not item.strip() or len(item) > 512 for item in value):
        raise CkbError(f"keyword benchmark {name} contains an invalid string")
    return [item.strip() for item in value]

def load_keyword_benchmark(path: Path) -> list[dict[str, Any]]:
    value = json_load(path.resolve())
    if not isinstance(value, dict) or set(value) != {"schema_version", "cases"}:
        raise CkbError("keyword benchmark file must contain only schema_version and cases")
    if value.get("schema_version") != KEYWORD_BENCHMARK_SCHEMA_VERSION:
        raise CkbError("keyword benchmark schema version mismatch")
    cases = value.get("cases")
    if not isinstance(cases, list) or not 1 <= len(cases) <= MAX_BENCHMARK_CASES:
        raise CkbError(f"keyword benchmark must contain 1 to {MAX_BENCHMARK_CASES} cases")
    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in cases:
        if not isinstance(item, dict):
            raise CkbError("keyword benchmark cases must be objects")
        allowed = {"id", "question", "expected_names", "expected_source_paths", "budget", "max_pages", "profile"}
        if set(item) - allowed:
            raise CkbError("keyword benchmark case contains unsupported fields")
        case_id = item.get("id")
        if not isinstance(case_id, str) or not _CASE_ID.fullmatch(case_id) or case_id in seen:
            raise CkbError("keyword benchmark case id must be unique and bounded")
        seen.add(case_id)
        question = item.get("question")
        if not isinstance(question, str) or not question.strip() or len(question) > 12_000:
            raise CkbError("keyword benchmark question must contain 1 to 12000 characters")
        budget = item.get("budget", 1800)
        max_pages = item.get("max_pages", 8)
        profile = item.get("profile", "fast")
        if isinstance(budget, bool) or not isinstance(budget, int) or not 200 <= budget <= 1_000_000:
            raise CkbError("keyword benchmark budget must be an integer in [200, 1000000]")
        if isinstance(max_pages, bool) or not isinstance(max_pages, int) or not 1 <= max_pages <= 32:
            raise CkbError("keyword benchmark max_pages must be an integer in [1, 32]")
        if profile not in {"fast", "precise"}:
            raise CkbError("keyword benchmark profile must be fast or precise")
        normalized.append(
            {
                "id": case_id,
                "question": question.strip(),
                "expected_names": _text_list(item.get("expected_names"), "expected_names"),
                "expected_source_paths": _text_list(item.get("expected_source_paths"), "expected_source_paths"),
                "budget": budget,
                "max_pages": max_pages,
                "profile": profile,
            }
        )
    return normalized

def _location(result: dict[str, Any], expected_names: list[str], expected_paths: list[str]) -> dict[str, Any]:
    selected = result.get("selected_entities") or []
    names = {
        str(value).casefold()
        for item in selected
        for value in (item.get("name"), item.get("qualified_name"))
        if value
    }
    paths = {str(item.get("source_path")).casefold() for item in selected if item.get("source_path")}
    expected_name_ids = {value.casefold() for value in expected_names}
    expected_path_ids = {value.replace("\\", "/").casefold() for value in expected_paths}
    matched_names = sorted(value for value in expected_names if value.casefold() in names)
    matched_paths = sorted(
        value
        for value in expected_paths
        if value.replace("\\", "/").casefold() in {path.replace("\\", "/") for path in paths}
    )
    total = len(expected_name_ids) + len(expected_path_ids)
    matched = len(matched_names) + len(matched_paths)
    return {
        "score": round(matched / total, 6) if total else 0.0,
        "matched_names": matched_names,
        "matched_source_paths": matched_paths,
        "selected_entities": len(selected),
        "selected_source_paths": len(paths),
        "estimated_tokens": result.get("estimated_tokens"),
        "status": result.get("status"),
    }

def keyword_cache_key(question: str, config: KeywordProviderConfig) -> str:
    validate_provider_config(config)
    material = {
        "input_hash": keyword_input_hash(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
    }
    serialized = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("ascii")).hexdigest()

def _machine_token(value: Any, name: str) -> str:
    if not isinstance(value, str) or not _MACHINE_TOKEN.fullmatch(value):
        raise CkbError(f"keyword provider {name} must be a bounded machine token")
    return value

def validate_provider_config(config: KeywordProviderConfig) -> None:
    if not config.command or any(not isinstance(value, str) or not value for value in config.command):
        raise CkbError("keyword provider command must contain at least one non-empty argument")
    _machine_token(config.provider, "provider")
    _machine_token(config.model, "model")
    _machine_token(config.version, "version")
    if not 0.1 <= config.timeout_seconds <= 300.0:
        raise CkbError("keyword provider timeout must be between 0.1 and 300 seconds")
    if config.retries not in {0, 1}:
        raise CkbError("keyword provider retries must be zero or one")
    for name in config.required_environment:
        if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", name):
            raise CkbError("keyword provider required environment names must be bounded identifiers")

def _bounded_strings(
    value: Any,
    *,
    name: str,
    maximum_items: int,
    maximum_chars: int,
    pattern: re.Pattern[str],
) -> list[str]:
    if not isinstance(value, list) or len(value) > maximum_items:
        raise CkbError(f"keyword provider {name} must be an array with at most {maximum_items} items")
    result: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, str):
            raise CkbError(f"keyword provider {name} items must be strings")
        normalized = item.strip()
        if not normalized or len(normalized) > maximum_chars:
            raise CkbError(f"keyword provider {name} items must contain 1 to {maximum_chars} characters")
        if not pattern.fullmatch(normalized):
            raise CkbError(f"keyword provider {name} contains unsupported characters")
        if _PROMPT_INJECTION.search(normalized):
            raise CkbError(f"keyword provider {name} contains prompt-injection text")
        if _CREDENTIAL_SHAPE.search(normalized):
            raise CkbError(f"keyword provider {name} contains credential-shaped text")
        identity = normalized.casefold()
        if identity in seen:
            raise CkbError(f"keyword provider {name} contains duplicate items")
        seen.add(identity)
        result.append(normalized)
    return result

def _usage(value: Any) -> dict[str, Any]:
    if value is None:
        value = {}
    if not isinstance(value, dict):
        raise CkbError("keyword provider usage must be an object")
    allowed = {"input_tokens", "output_tokens", "total_tokens", "cost_usd"}
    if set(value) - allowed:
        raise CkbError("keyword provider usage contains unsupported fields")
    result: dict[str, Any] = {}
    for name in ("input_tokens", "output_tokens", "total_tokens"):
        item = value.get(name, 0)
        if isinstance(item, bool) or not isinstance(item, int) or item < 0:
            raise CkbError(f"keyword provider usage {name} must be a non-negative integer")
        result[name] = item
    cost = value.get("cost_usd", 0.0)
    if isinstance(cost, bool) or not isinstance(cost, (int, float)) or cost < 0:
        raise CkbError("keyword provider usage cost_usd must be a non-negative number")
    result["cost_usd"] = round(float(cost), 8)
    if result["total_tokens"] and result["total_tokens"] != result["input_tokens"] + result["output_tokens"]:
        raise CkbError("keyword provider usage total_tokens does not match input plus output")
    return result

def parse_provider_json(raw: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise CkbError("keyword provider returned invalid JSON") from exc

def _read_cache(output: Path, question: str, config: KeywordProviderConfig) -> dict[str, Any] | None:
    path = _cache_path(output, keyword_cache_key(question, config))
    if not path.is_file():
        return None
    try:
        record = json_load(path)
        expected = _cache_record(question, config, record.get("response") if isinstance(record, dict) else {})
        if not isinstance(record, dict) or set(record) != _CACHE_FIELDS:
            return None
        for name in _CACHE_FIELDS - {"response"}:
            if record.get(name) != expected.get(name):
                return None
        response = validate_provider_response(record.get("response"), question=question, config=config)
        if response.get("status") != "passed":
            return None
        return response
    except (CkbError, OSError, ValueError, TypeError):
        return None

def audit_keyword_cache(output: Path) -> dict[str, Any]:
    """Check bounded cache records without reading or requiring provider secrets."""

    root = output.resolve() / "workspace-meta" / "keyword-fallback" / "cache"
    if not root.is_dir():
        return {"schema_version": 1, "status": "passed", "records": 0, "errors": []}
    errors: list[str] = []
    records = 0
    for path in sorted(root.glob("*.json")):
        records += 1
        try:
            value = json_load(path)
        except (OSError, ValueError) as exc:
            errors.append(f"{path.name}: invalid cache JSON: {type(exc).__name__}")
            continue
        if not isinstance(value, dict) or set(value) != _CACHE_FIELDS:
            errors.append(f"{path.name}: fields differ from the fixed cache schema")
            continue
        if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION or value.get("status") != "passed":
            errors.append(f"{path.name}: cache status or schema mismatch")
        if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
            errors.append(f"{path.name}: prompt schema mismatch")
        cache_key = value.get("cache_key")
        if not isinstance(cache_key, str) or not re.fullmatch(r"[0-9a-f]{64}", cache_key) or path.stem != cache_key:
            errors.append(f"{path.name}: cache key mismatch")
        input_hash = value.get("input_hash")
        if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
            errors.append(f"{path.name}: input hash is invalid")
        for name in ("provider", "model", "version"):
            try:
                _machine_token(value.get(name), name)
            except CkbError as exc:
                errors.append(f"{path.name}: {exc}")
        serialized = json.dumps(value, ensure_ascii=False)
        if _CREDENTIAL_SHAPE.search(serialized):
            errors.append(f"{path.name}: cache contains credential-shaped text")
    unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
    errors.extend(f"unexpected keyword cache entry: {name}" for name in sorted(unexpected))
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "records": records,
        "errors": errors,
    }
